><section class="rounded-xl border border-stone-200 bg-white p-6"><h2 class="font-semibold">Final decision</h2><p class="mt-3 text-sm leading-6 text-stone-600">{{ refund.decision_reason }}</p><p v-if="refund.escalation_reason" class="mt-3 rounded-lg bg-amber-50 p-3 text-xs text-amber-950">{{ refund.escalation_reason }}</p></section><section class="rounded-xl border border-stone-200 bg-white p-6"><h2 class="font-semibold">Audit trail</h2><ol class="mt-4 space-y-4"> <li v-for="entry in logs" :key="entry.id" class="relative border-l border-stone-200 pl-4"><span class="absolute -left-1 top-1 h-2 w-2 rounded-full bg-amber-500"></span><p class="text-sm font-medium">{{ entry.event.replaceAll('_',' ') }}</p><p class="mt-1 text-xs text-stone-400">{{ new Date(entry.created_at).toLocaleString() }}</p></li></ol></section></aside></div></AppLayout></template>
